{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Previous LTPA-focussed research has mostly been quantified by time, frequency, and/or intensity (e.g., light intensity, moderate-vigorous intensity), with little investigation into the impact of the specific activity types of LTPA being performed [12-15]. The World Health Organisation Physical Activity and Sedentary Behaviour Guidelines Development Group [14] identified understanding the health effects of different PA types as one of four major evidence gaps in current knowledge.",
      "reason": "The Introduction describes the current state of knowledge (PA-LTPA research to date) and explicitly identifies uncertainties/evidence gaps, including the WHO-identified gap regarding health effects of different PA types."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Therefore, summarising the current state of knowledge of the longitudinal health and behavioural effects of specific LTPA types could help inform public health policy and direct future research... Such knowledge may assist in reducing the global burden of major diseases, including cardiovascular disease and mental health disorders, and further, achieving PA targets for improved population health.",
      "reason": "The importance and need for the review are clearly explained in terms of public health burden, policy relevance, and directing future research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Previous systematic reviews have highlighted the influence of activity structure and type on psychosocial outcomes in children [22] and cardiovascular health in adults [23]. Another review identified a largely positive relationship between overall childhood sport participation and adulthood PA [24]. However, the longitudinal associations between participation in specific LTPA types during childhood and adolescence and adult health and PA behaviours remains unknown.",
      "reason": "Existing similar systematic reviews are cited and the need for the current review is explained by identifying what those reviews did not address (specific LTPA types and longitudinal adult outcomes)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of associations between LTPA types and later outcomes, not a review of intervention effects, so no proposed mechanism of intervention action is required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines exposure-outcome associations in observational longitudinal studies, not a complex intervention or delivery context, so a logic model is not required."
    }
  ],
  "confidence": 92
}

